@startuml

class Resident {
  + name : string
  + streetAddress : string
  + phoneNumber : string
  + emailAddress : string
}

class PickupRequest {
  + streetAddress : string
  + description : string
  + pickupTime : time
}

class Vehicle {
  + storageSpace : float
}

class VolunteerDriver {
  + availableDays : string[]
}

class PickupRoute {
  + date : date
}

class Item {
  + description : string
  + dimensions : string
  + weight : float
}

class SecondHandArticle {
  + rfidTag : string
  + correctedDescription : string
}

class FoodItem {}

class Category {
  + name : string
}

class Client {
  + homeAddress : string
}

class H2SLocation {
  + city : string
}

class H2SEmployee {
  + name : string
}

class Delivery {
  + deliveryDate : date
}

Resident "1" -- "*" PickupRequest
Resident "1" -- "*" Item
Resident "0..1" -- "*" Client
PickupRequest "1" -- "*" Item
Vehicle "1" -- "*" PickupRoute
VolunteerDriver "1" -- "*" PickupRoute
PickupRoute "1" *-- "*" Item
Item <|-- SecondHandArticle
Item <|-- FoodItem
SecondHandArticle "*" -- "1" Category
SecondHandArticle "*" -- "1" H2SEmployee
Client "1" -- "*" Delivery
VolunteerDriver "1" -- "*" Delivery
Delivery "*" -- "1" SecondHandArticle
H2SLocation "1" -- "*" H2SEmployee
H2SLocation "1" -- "*" Vehicle
H2SLocation "1" -- "*" VolunteerDriver
H2SLocation "1" -- "*" Resident

@enduml

